	// RESULT-3: CONFIRMED (actual=5933.73095)

	scores := make(map[string]float64, len(snapshots))

	// Compute cluster load statistics
	totalLoad := 0.0
	maxLoad := 0.0
	for _, snap := range snapshots {
		l := float64(snap.EffectiveLoad())
		totalLoad += l
		if l > maxLoad {
			maxLoad = l
		}
	}
	avgLoad := totalLoad / float64(len(snapshots))

	// Load pressure: sigmoid-style saturation (0 at low load, approaches 1 at high load)
	loadPressure := avgLoad / (avgLoad + 3.5)

	// Input size factor for cache affinity
	inputLen := float64(len(req.InputTokens))
	inputFactor := inputLen / (inputLen + 256.0)

	// Dynamic weight adjustment per scorer dimension
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}

			w := ws.weights[i]
			if i == 0 {
				// prefix-affinity: preserve weight at low load, reduce under pressure
				// Large inputs benefit more from cache when load is low
				w *= (1.0 - 0.65*loadPressure) * (1.0 + 0.25*inputFactor*(1.0-loadPressure))
			} else {
				// load-balance: boost under load, especially for large inputs
				w *= (1.0 + 0.7*loadPressure) * (1.0 + 0.15*inputFactor*loadPressure)
			}
			scores[snap.ID] += s * w
		}
